package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps each sheet's plans, and makes their claims. */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PersonRepository people;
    private final ClaimService claims;
    private final SheetService sheets;
    private final RoleService roles;
    private final Audit audit;

    public PlanService(PlanRepository plans, PersonRepository people, ClaimService claims, SheetService sheets,
            RoleService roles, Audit audit) {
        this.roles = roles;
        this.plans = plans;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's plans, in the order they were added. */
    @Transactional(readOnly = true)
    public List<Plan> list(String sheetId) {
        sheets.today(sheetId);
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The sheet's today, from which the plans' next dates are told. */
    @Transactional(readOnly = true)
    public LocalDate today(String sheetId) {
        return sheets.today(sheetId);
    }

    /** Add a plan to a person, run every so many days or monthly on a day of the month (exactly one of them);
     *  an amount a claim would refuse (below 0.00), an interval below 1 day, a day of the month outside 1 to 31,
     *  or an end before the start is refused. It may name one of the sheet's descendants to make its claims
     *  on; a sheet that is not a descendant is refused. */
    @Transactional
    public Plan add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start,
            Integer every, Integer day, LocalDate end, String targetSheet) {
        sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (amount.signum() < 0) {
            throw new PlanRefusedException("Enter an amount of 0.00 or more.");
        }
        if (day != null) {
            if (every != null) {
                throw new PlanRefusedException("Enter either every how many days or a day of the month, not both.");
            }
            if (day < 1 || day > 31) {
                throw new PlanRefusedException("Enter a day of the month from 1 to 31.");
            }
        } else if (every == null || every < 1) {
            throw new PlanRefusedException("Enter every how many days, 1 or more.");
        }
        if (end.isBefore(start)) {
            throw new PlanRefusedException("The end cannot be before the start.");
        }
        String target = targetSheet == null || targetSheet.isBlank() ? null : targetSheet.trim();
        if (target != null && !sheets.isDescendant(target, sheetId)) {
            throw new PlanRefusedException("The sheet must be a descendant of this sheet.");
        }
        BigDecimal a = amount.setScale(2);
        Plan plan = plans.saveAndFlush(new Plan(sheetId, personId, a, start, every, day, end, target));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " amount=" + a.toPlainString() + " start=" + start
                + (day != null ? " day=" + day : " every=" + every) + " end=" + end
                + (target != null ? " sheet=" + target : ""));
        return plan;
    }

    /** Pause a running plan, or resume a paused one, from the sheet's today: plan dates from the day paused
     *  until the day resumed are skipped. Pausing a paused plan or resuming a running one is refused. */
    @Transactional
    public Plan setPaused(String sheetId, String user, long planId, boolean paused) {
        LocalDate today = sheets.today(sheetId);
        Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new PlanRefusedException("No such plan."));
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        if (paused == plan.isPaused()) {
            throw new PlanRefusedException(paused ? "The plan is already paused." : "The plan is not paused.");
        }
        if (paused) {
            plan.pause(today);
        } else {
            plan.resume(today);
        }
        plan = plans.saveAndFlush(plan);
        audit.recordOnCommit((paused ? "PLAN_PAUSED" : "PLAN_RESUMED") + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " start=" + plan.getStart());
        return plan;
    }

    /** Change a plan's amount from the sheet's today: the claims it makes from then on carry the new amount,
     *  those already made keep theirs. An amount a claim would refuse (below 0.00) is refused. */
    @Transactional
    public Plan changeAmount(String sheetId, String user, long planId, BigDecimal amount) {
        LocalDate today = sheets.today(sheetId);
        Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new PlanRefusedException("No such plan."));
        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        if (amount.signum() < 0) {
            throw new PlanRefusedException("Enter an amount of 0.00 or more.");
        }
        BigDecimal a = amount.setScale(2);
        plan.changeAmount(today, a);
        plan = plans.saveAndFlush(plan);
        audit.recordOnCommit("PLAN_CHANGED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " start=" + plan.getStart() + " amount=" + a.toPlainString());
        return plan;
    }

    /** What a generate did: the claims it made, in the order made, the sheet's plans, and its today. */
    public record Generated(List<Claim> claims, List<Plan> plans, LocalDate today) {
    }

    /** For every plan on the sheet in the order they were added, make a DRAFT claim of its amount with an
     *  empty note on each plan date up to its end and the sheet's today it has made none for yet; a date the
     *  claim form refuses is skipped, and tried again next time. Like a bulk action, a viewer's generate goes
     *  through with nothing made. A plan naming a descendant sheet makes its claims there, for the person of
     *  the same name on that sheet (none when there is no such person), by that sheet's rules. */
    @Transactional
    public Generated generate(String sheetId, String user) {
        LocalDate today = sheets.today(sheetId);
        List<Plan> all = plans.findBySheetIdOrderByIdAsc(sheetId);
        if (roles.isViewer(sheetId, user)) {
            return new Generated(List.of(), all, today);
        }
        List<Claim> made = new ArrayList<>();
        for (Plan plan : all) {
            Optional<Person> person = people.findByIdAndSheetId(plan.getPersonId(), sheetId);
            if (person.isEmpty()) {
                continue; // the person is no longer on the sheet
            }
            String on = plan.getTargetSheet() != null ? plan.getTargetSheet() : sheetId;
            Optional<Person> claimant = on.equals(sheetId) ? person : people.findByName(on, person.get().getName());
            if (claimant.isEmpty()) {
                continue; // no one of that name on the descendant sheet
            }
            long claimantId = claimant.get().getId();
            for (LocalDate date : plan.datesDue(today)) {
                claims.addIfAccepted(on, user, claimantId, plan.getAmount(), date, "")
                        .ifPresent(claim -> {
                            made.add(claim);
                            plan.generated(date);
                        });
            }
            plans.saveAndFlush(plan);
        }
        return new Generated(made, all, today);
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person's plan: a DRAFT claim of its amount on every plan date up to its end — the start then every so
 *  many days, or monthly on a day of the month — and the plan dates it has made a claim for so far. */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private long personId;

    @Column(name = "amount", nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    /** Every so many days; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) of a monthly plan; null for one run every so many days. */
    @Column(name = "month_day")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    /** The descendant sheet whose person of the same name its claims are made for; null for its own sheet. */
    @Column(name = "target_sheet")
    private String targetSheet;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_generated", joinColumns = @JoinColumn(name = "plan_id"))
    @Column(name = "on_date")
    private Set<LocalDate> generated = new HashSet<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    private List<PlanPause> pauses = new ArrayList<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_change", joinColumns = @JoinColumn(name = "plan_id"))
    @OrderColumn(name = "seq")
    private List<PlanChange> changes = new ArrayList<>();

    protected Plan() {
    }

    public Plan(String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end, String targetSheet) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
        this.targetSheet = targetSheet;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    /** The descendant sheet its claims are made on; null for its own sheet. */
    public String getTargetSheet() {
        return targetSheet;
    }

    /** The changes of its amount, oldest first. */
    public List<PlanChange> getChanges() {
        return List.copyOf(changes);
    }

    /** Change the amount of the claims it makes from the given day on; those already made keep theirs. */
    public void changeAmount(LocalDate on, BigDecimal newAmount) {
        changes.add(new PlanChange(on, newAmount));
        this.amount = newAmount;
    }

    /** How many claims the plan has made so far. */
    public int getGeneratedCount() {
        return generated.size();
    }

    /** Whether the plan is paused and not yet resumed. */
    public boolean isPaused() {
        return pauses.stream().anyMatch(p -> p.getResumedOn() == null);
    }

    /** Pause the plan from the given day. */
    public void pause(LocalDate on) {
        pauses.add(new PlanPause(on));
    }

    /** Resume the paused plan from the given day. */
    public void resume(LocalDate on) {
        pauses.stream().filter(p -> p.getResumedOn() == null).forEach(p -> p.resume(on));
    }

    /** The plan dates up to its end and the given day that it has made no claim for yet and that no pause
     *  skips, earliest first. */
    public List<LocalDate> datesDue(LocalDate today) {
        LocalDate last = end.isBefore(today) ? end : today;
        return dates(start, last, Integer.MAX_VALUE).stream().filter(d -> !generated.contains(d)).toList();
    }

    /** The first so many plan dates after the given day and on or before its end that no pause skips,
     *  earliest first, whether or not it has made a claim for them. A plan still paused has none. */
    public List<LocalDate> nextDates(LocalDate today, int count) {
        if (isPaused()) {
            return List.of();
        }
        return dates(today.plusDays(1), end, count);
    }

    private boolean skipped(LocalDate date) {
        return pauses.stream().anyMatch(p -> p.skips(date));
    }

    /** The plan dates from the given first to last day that no pause skips, earliest first, at most so many. A monthly plan's dates
     *  are its day in every month from the start's month, a day beyond the month's length falling on its last
     *  day, dates before the start left out. */
    private List<LocalDate> dates(LocalDate first, LocalDate last, int max) {
        List<LocalDate> out = new ArrayList<>();
        if (day != null) {
            for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last) && out.size() < max;
                    m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isBefore(first) && !d.isAfter(last) && !skipped(d)) {
                    out.add(d);
                }
            }
            return out;
        }
        LocalDate d = start;
        if (d.isBefore(first)) {
            long steps = (ChronoUnit.DAYS.between(start, first) + every - 1) / every;
            d = start.plusDays(steps * every);
        }
        for (; !d.isAfter(last) && out.size() < max; d = d.plusDays(every)) {
            if (!skipped(d)) {
                out.add(d);
            }
        }
        return out;
    }

    /** Keep that the plan has made its claim for the plan date. */
    public void generated(LocalDate date) {
        generated.add(date);
    }
}
